def main():
    # Vamos a calcular 2^1000 multiplicando por 2 repetidamente en base 10 (con listas de dígitos)
    # para asegurar que no haya ningún problema de representación o conversión.

    digits = [1]

    for _ in range(1000):
        carry = 0
        for i in range(len(digits)):
            val = digits[i] * 2 + carry
            digits[i] = val % 10
            carry = val // 10
        if carry > 0:
            digits.append(carry)

    print(sum(digits))

